// ==========================================
// SIGNAL PARSER CONFIGURATION
// ==========================================
// Parses trading signals from Telegram messages
// Supports common signal formats:
//   BUY BTCUSDT 95000
//   SELL ETHUSDT market
//   LONG SOLUSDT 180 TP:200 SL:170

const message = $input.first().json.message?.text || '';
const chatId = $input.first().json.message?.chat?.id?.toString() || '';

// ALLOWED CHAT IDS - only process signals from these chats
// Add your signal channel/group chat IDs here
const ALLOWED_CHATS = [
  // '-1001234567890', // Example group
  // '123456789',      // Example user
];

// If ALLOWED_CHATS is empty, process all messages (for testing)
if (ALLOWED_CHATS.length > 0 && !ALLOWED_CHATS.includes(chatId)) {
  return [{ json: { skip: true, reason: 'Unauthorized chat' } }];
}

// Parse signal
const lines = message.toUpperCase().split('\n').map(l => l.trim());
const fullText = lines.join(' ');

let signal = {
  parsed: false,
  side: null,
  symbol: null,
  price: null,
  orderType: 'Market',
  takeProfit: null,
  stopLoss: null,
  rawMessage: message
};

// Pattern: BUY/SELL/LONG/SHORT SYMBOL [PRICE]
const mainPattern = /(BUY|SELL|LONG|SHORT)\s+([A-Z0-9]+USDT?)\s*(\d+\.?\d*|MARKET)?/;
const match = fullText.match(mainPattern);

if (match) {
  signal.parsed = true;
  signal.side = (match[1] === 'BUY' || match[1] === 'LONG') ? 'Buy' : 'Sell';
  signal.symbol = match[2];

  if (match[3] && match[3] !== 'MARKET') {
    signal.price = parseFloat(match[3]);
    signal.orderType = 'Limit';
  }

  // Parse TP (Take Profit)
  const tpMatch = fullText.match(/TP[:\s]*(\d+\.?\d*)/);
  if (tpMatch) signal.takeProfit = parseFloat(tpMatch[1]);

  // Parse SL (Stop Loss)
  const slMatch = fullText.match(/SL[:\s]*(\d+\.?\d*)/);
  if (slMatch) signal.stopLoss = parseFloat(slMatch[1]);
}

return [{ json: signal }];

const signal = $input.first().json;
const crypto = require('crypto');

// Configuration
const USE_TESTNET = true; // SET TO true FOR TESTING!
const ORDER_AMOUNT_USDT = 50; // Amount per signal order

const baseUrl = USE_TESTNET
  ? 'https://api-testnet.bybit.com'
  : 'https://api.bybit.com';

const apiKey = $env.BYBIT_API_KEY;
const apiSecret = $env.BYBIT_API_SECRET;
const timestamp = Date.now().toString();
const recvWindow = '5000';

// Get current price for quantity calculation
const tickerResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/v5/market/tickers?category=spot&symbol=${signal.symbol}`,
});

const currentPrice = parseFloat(tickerResponse.result.list[0].lastPrice);
const orderPrice = signal.price || currentPrice;
const qty = (ORDER_AMOUNT_USDT / orderPrice).toFixed(6);

// Create order
const orderPayload = {
  category: 'spot',
  symbol: signal.symbol,
  side: signal.side,
  orderType: signal.orderType,
  qty: signal.orderType === 'Market' && signal.side === 'Buy' 
    ? ORDER_AMOUNT_USDT.toString() 
    : qty,
  ...(signal.orderType === 'Market' && signal.side === 'Buy' 
    ? { marketUnit: 'quoteCoin' } 
    : {}),
  ...(signal.orderType === 'Limit' ? { price: orderPrice.toString() } : {})
};

const bodyStr = JSON.stringify(orderPayload);
const preSign = timestamp + apiKey + recvWindow + bodyStr;
const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');

let response;
try {
  response = await this.helpers.httpRequest({
    method: 'POST',
    url: `${baseUrl}/v5/order/create`,
    headers: {
      'X-BAPI-API-KEY': apiKey,
      'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp,
      'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    },
    body: orderPayload
  });
} catch(e) {
  response = { retCode: -1, retMsg: e.message };
}

return [{
  json: {
    success: response.retCode === 0,
    symbol: signal.symbol,
    side: signal.side,
    orderType: signal.orderType,
    price: orderPrice,
    qty: qty,
    amountUSDT: ORDER_AMOUNT_USDT,
    orderId: response.result?.orderId || 'N/A',
    retCode: response.retCode,
    retMsg: response.retMsg,
    takeProfit: signal.takeProfit,
    stopLoss: signal.stopLoss,
    rawSignal: signal.rawMessage
  }
}];

const data = $input.first().json;

const emoji = data.success ? '✅' : '❌';
const sideEmoji = data.side === 'Buy' ? '🟢' : '🔴';

let message = `${emoji} <b>Signal Copier</b>\n\n`;
message += `${sideEmoji} <b>${data.side} ${data.symbol}</b>\n`;
message += `<b>Тип:</b> ${data.orderType}\n`;
message += `<b>Цена:</b> <code>$${data.price}</code>\n`;
message += `<b>Кол-во:</b> ${data.qty} (~$${data.amountUSDT})\n`;

if (data.success) {
  message += `<b>Order ID:</b> <code>${data.orderId}</code>\n`;
} else {
  message += `<b>Ошибка:</b> ${data.retMsg}\n`;
}

if (data.takeProfit) message += `<b>TP:</b> $${data.takeProfit}\n`;
if (data.stopLoss) message += `<b>SL:</b> $${data.stopLoss}\n`;

message += `\n<b>Исходный сигнал:</b>\n<i>${data.rawSignal}</i>`;
message += `\n\n⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

return [{ json: { message } }];
